    #[test]
    fn revoke_then_rebind_restores_attestable_key() {
        let conn = test_db();
        register_agent(&conn, "ai:curator", "ai:generic", &[]).expect("register");
        let k1 = crate::identity::keypair::generate("ai:curator")
            .unwrap()
            .public_base64();
        bind_agent_pubkey(&conn, "ai:curator", &k1).expect("bind k1");
        revoke_agent_pubkey(&conn, "ai:curator").expect("revoke");
        assert_eq!(agent_pubkey(&conn, "ai:curator").unwrap(), None);
        let k2 = crate::identity::keypair::generate("ai:curator")
            .unwrap()
            .public_base64();
        bind_agent_pubkey(&conn, "ai:curator", &k2).expect("rebind k2");
        assert_eq!(agent_pubkey(&conn, "ai:curator").unwrap(), Some(k2));
    }

    #[test]
    fn sync_state_merge_applies_pointwise_max_and_never_regresses() {
        // v0.8.0 Pillar-3 (#1709) / #224 Task 3a.1 — fold an incoming
        // peer clock into the persisted sync-state via pointwise max:
        // a NEW peer is added, a NEWER timestamp advances an existing
        // peer, and an OLDER incoming timestamp must NOT regress a newer
        // stored entry.
        let conn = test_db();
        let local = "ai:receiver";
        // Seed the receiver clock: p-existing at a mid timestamp.
        sync_state_observe(&conn, local, "p-existing", "2026-03-01T00:00:00Z").expect("seed");
        sync_state_observe(&conn, local, "p-stable", "2026-05-01T00:00:00Z").expect("seed2");

        let mut incoming = crate::models::VectorClock::default();
        incoming.observe("p-existing", "2026-04-01T00:00:00Z"); // newer → wins
        incoming.observe("p-stable", "2026-01-01T00:00:00Z"); // older → must NOT regress
        incoming.observe("p-new", "2026-02-01T00:00:00Z"); // new peer → added

        sync_state_merge(&conn, local, &incoming).expect("merge");

        let merged = sync_state_load(&conn, local).expect("reload");
        assert_eq!(
            merged.latest_from("p-existing"),
            Some("2026-04-01T00:00:00Z")
        );
        assert_eq!(merged.latest_from("p-stable"), Some("2026-05-01T00:00:00Z"));
        assert_eq!(merged.latest_from("p-new"), Some("2026-02-01T00:00:00Z"));
    }

    // -----------------------------------------------------------------------
    // v1.0.0 R19/A3 (#1948) — fail-closed lifecycle-visibility allow-list.
    //
    // One regression test PER read/egress lane proving a Tombstoned row (THE
    // LIVE BUG — no SQL predicate excluded it before this change) AND a
    // Quarantined row are BOTH invisible, while an Open row still surfaces.
    // -----------------------------------------------------------------------

    fn raw_set_lifecycle(conn: &Connection, id: &str, state: &str) {
        // Raw UPDATE — deliberately bypasses the `set_lifecycle_state`
        // transition gate to plant a terminal system-only state, exactly as
        // the tombstone / quarantine system paths do.
        conn.execute(
            "UPDATE memories SET lifecycle_state = ?1 WHERE id = ?2",
            rusqlite::params![state, id],
        )
        .unwrap();
    }

    /// Insert three rows sharing the searchable token "widget": one Open
    /// (visible), one raw-Tombstoned, one raw-Quarantined. Returns
    /// `(open_id, tomb_id, quar_id)`.
    fn seed_lifecycle_corpus(conn: &Connection, ns: &str) -> (String, String, String) {
        let vis = insert(conn, &make_memory("widget open", ns, Tier::Long, 5)).unwrap();
        let tomb = insert(conn, &make_memory("widget tomb", ns, Tier::Long, 5)).unwrap();
        let quar = insert(conn, &make_memory("widget quar", ns, Tier::Long, 5)).unwrap();
        raw_set_lifecycle(conn, &tomb, "tombstoned");
        raw_set_lifecycle(conn, &quar, "quarantined");
        (vis, tomb, quar)
    }

    #[test]
    fn lifecycle_allowlist_lane_recall() {
        let conn = test_db();
        let (vis, tomb, quar) = seed_lifecycle_corpus(&conn, "ns/life");
        let (rows, _) = recall(
            &conn, "widget", None, 50, None, None, None, 0, 0, None, None, false, None, None,
            None, // #1834 valid_at
        )
        .unwrap();
        let ids: Vec<&str> = rows.iter().map(|(m, _)| m.id.as_str()).collect();
        assert!(
            ids.contains(&vis.as_str()),
            "open row must surface in recall"
        );
        assert!(
            !ids.contains(&tomb.as_str()),
            "LIVE BUG: tombstoned row leaked into recall"
        );
        assert!(
            !ids.contains(&quar.as_str()),
            "quarantined row leaked into recall"
        );
    }

